name: "checkInstalledExtensions",
task: async () => {
  lazy.AddonManager.addAddonListener({
    onInstalled() {
      lazy.checkInstalledExtensions();
    },
    onUninstalled() {
      lazy.checkInstalledExtensions();
    },
    onDisabled() {
      lazy.checkInstalledExtensions();
    },
    onEnabled() {
      lazy.checkInstalledExtensions();
    },
  });
  await lazy.checkInstalledExtensions();
  Services.prefs.addObserver(
    "extensions.experiments.suppressed",
    () => {
      lazy.checkInstalledExtensions();
    }
  );
},
